// ============================================================================
// Memory Strategy Configuration Based on Detected Hardware
// ============================================================================

/**
 * Configure memory strategy based on detected hardware
 */
static void configure_memory_strategy(BootloaderState* state) {
    BootHardwareInfo* hw = &state->hardware;
    memory_strategy_config_t* cfg = &state->memory_config;
    
    // Initialize with defaults
    *cfg = GUIKIT_MEMORY_STRATEGY_DEFAULT;
    
    // Adjust thresholds based on available hardware
    
    // If we have external RAM (SRAM or PSRAM), use it for larger GUIs
    if (hw->sram_detected || hw->psram_detected) {
        uint32_t total_external = hw->sram_size + hw->psram_size;
        
        // Use external RAM for GUIs larger than 4KB
        cfg->external_ram_min_size = 4096;
        
        // Set max external RAM size based on what's available
        cfg->external_ram_max_size = total_external;
        
        // If we have a lot of external RAM (> 512KB), increase the threshold
        if (total_external > 512 * 1024) {
            cfg->external_ram_min_size = 16384;  // Use external RAM for GUIs > 16KB
        }
        
        // Always try external RAM first
        cfg->use_external_ram_by_default = true;
    } else {
        // No external RAM - disable it
        cfg->use_external_ram_by_default = false;
        cfg->external_ram_min_size = UINT32_MAX;  // Never use
    }
    
    // If we have SD card, enable SD swap
    if (hw->sdcard_detected) {
        cfg->use_sd_swap_by_default = true;
        
        // If we have limited internal RAM (ESP8266), use SD swap for medium-sized GUIs
        // If we have lots of internal RAM (ESP32), only use SD swap for very large GUIs
        #if defined(ESP8266)
            cfg->sd_swap_min_size = 8192;  // Use SD swap for GUIs > 8KB on ESP8266
        #elif defined(ESP32)
            cfg->sd_swap_min_size = 32768;  // Use SD swap for GUIs > 32KB on ESP32
        #else
            cfg->sd_swap_min_size = 16384;  // Default: 16KB
        #endif
    } else {
        // No SD card - disable SD swap
        cfg->use_sd_swap_by_default = false;
        cfg->sd_swap_min_size = UINT32_MAX;  // Never use
    }
    
    // Adjust internal RAM max based on platform
    #if defined(ESP8266)
        // ESP8266 has ~80KB free RAM, reserve some for system
        cfg->internal_ram_max_size = 65536;  // 64KB max for internal RAM
    #elif defined(ESP32)
        // ESP32 has more RAM
        cfg->internal_ram_max_size = 262144;  // 256KB max for internal RAM
    #else
        cfg->internal_ram_max_size = 8192;  // Default: 8KB
    #endif
    
    // Set SD swap cache size based on available internal RAM
    #if defined(ESP8266)
        cfg->sd_swap_cache_size = 2048;  // 2KB cache on ESP8266
    #elif defined(ESP32)
        cfg->sd_swap_cache_size = 8192;  // 8KB cache on ESP32
    #else
        cfg->sd_swap_cache_size = 4096;  // 4KB default
    #endif
    
    // Always check memory before loading
    cfg->check_memory_before_load = true;
    
    // Display errors on TFT if available
    cfg->display_error_on_tft = hw->tft_detected;
}

