/**
 * Initialize SPI bus
 */
static bool spi_init(uint8_t sck_pin, uint8_t mosi_pin, uint8_t miso_pin, uint8_t max_speed_mhz) {
    // In a real implementation, this would configure the SPI bus
    printf("[SPI] Initializing: SCK=%d, MOSI=%d, MISO=%d, Speed=%d MHz\n",
           sck_pin, mosi_pin, miso_pin, max_speed_mhz);
    return true;
}

/**
 * Detect all SPI devices and populate hardware info
 */
static void detect_spi_devices(BootloaderState* state) {
    guikit_spi_config_t* spi_cfg = &state->config.spi;
    BootHardwareInfo* hw = &state->hardware;
    
    // Initialize SPI bus
    if (!spi_init(spi_cfg->sck_pin, spi_cfg->mosi_pin, spi_cfg->miso_pin, spi_cfg->max_speed_mhz)) {
        state->current_state = BOOT_STATE_ERROR;
        state->error_message = "Failed to initialize SPI bus";
        return;
    }
    
    // Detect each SPI device in the configuration
    for (int i = 0; i < spi_cfg->bank_count; i++) {
        guikit_spi_bank_t* bank = &spi_cfg->bank[i];
        
        if (!bank->enabled) continue;
        
        // Try to detect SRAM
        uint32_t sram_size;
        const char* sram_type;
        if (detect_spi_sram(bank->cs_pin, &sram_size, &sram_type)) {
            hw->sram_detected = true;
            hw->sram_size = sram_size;
            hw->sram_cs_pin = bank->cs_pin;
            hw->sram_type = sram_type;
            printf("[SPI] SRAM detected at CS %d: %s, %lu KB\n", bank->cs_pin, sram_type, sram_size / 1024);
            continue;  // This bank is SRAM, skip other checks
        }
        
        // Try to detect PSRAM
        uint32_t psram_size;
        if (detect_spi_psram(bank->cs_pin, &psram_size)) {
            hw->psram_detected = true;
            hw->psram_size = psram_size;
            printf("[SPI] PSRAM detected at CS %d: %lu KB\n", bank->cs_pin, psram_size / 1024);
            continue;  // This bank is PSRAM, skip other checks
        }
        
        // Try to detect SD Card
        if (detect_sd_card(bank->cs_pin)) {
            hw->sdcard_detected = true;
            hw->sdcard_cs_pin = bank->cs_pin;
            printf("[SPI] SD Card detected at CS %d\n", bank->cs_pin);
            continue;  // This bank is SD Card, skip other checks
        }
        
        // Try to detect TFT
        uint16_t tft_w, tft_h;
        if (detect_tft(bank->cs_pin, &tft_w, &tft_h)) {
            hw->tft_detected = true;
            hw->tft_width = tft_w;
            hw->tft_height = tft_h;
            hw->tft_cs_pin = bank->cs_pin;
            printf("[SPI] TFT detected at CS %d: %dx%d\n", bank->cs_pin, tft_w, tft_h);
            continue;  // This bank is TFT, skip other checks
        }
        
        // Try to detect Touch
        if (detect_touch(bank->cs_pin)) {
            hw->touch_detected = true;
            hw->touch_cs_pin = bank->cs_pin;
            printf("[SPI] Touch detected at CS %d\n", bank->cs_pin);
            continue;  // This bank is Touch, skip other checks
        }
        
        // Try to detect SPI expander
        guikit_expander_type_t exp_type;
        if (detect_spi_expander(bank->cs_pin, &exp_type)) {
            hw->spi_expander_count++;
            switch (exp_type) {
                case GUIKIT_EXPANDER_MCP23S17:
                case GUIKIT_EXPANDER_MCP23017:
                    hw->total_expander_gpio += 16;
                    break;
                case GUIKIT_EXPANDER_MCP23S08:
                case GUIKIT_EXPANDER_MCP23008:
                    hw->total_expander_gpio += 8;
                    break;
                default:
                    break;
            }
            printf("[SPI] Expander detected at CS %d: %d\n", bank->cs_pin, exp_type);
        }
    }
}

/**
 * Initialize RAM (internal and external)
 */
static bool init_ram(BootloaderState* state) {
    BootHardwareInfo* hw = &state->hardware;
    guikit_ram_config_t* ram_cfg = &state->config.ram;
    
    // Internal RAM is always available
    ram_cfg->internal = true;
    
    // Initialize external RAM banks
    ram_cfg->bank_count = 0;
    
    // If SRAM was detected, add it to the configuration
    if (hw->sram_detected) {
        guikit_ram_bank_t* bank = &ram_cfg->bank[ram_cfg->bank_count++];
        bank->type = GUIKIT_RAM_SRAM;
        bank->size = hw->sram_size;
        bank->cs_pin = hw->sram_cs_pin;
        bank->enabled = true;
        
        // Create SRAM instance (mock)
        state->sram_instance = nullptr;  // Would be new SPISRAM(hw->sram_cs_pin)
        printf("[RAM] SRAM initialized: %lu KB at CS %d\n", hw->sram_size / 1024, hw->sram_cs_pin);
    }
    
    // If PSRAM was detected, add it to the configuration
    if (hw->psram_detected) {
        guikit_ram_bank_t* bank = &ram_cfg->bank[ram_cfg->bank_count++];
        bank->type = GUIKIT_RAM_PSRAM;
        bank->size = hw->psram_size;
        bank->cs_pin = 255;  // PSRAM uses internal connection on ESP32
        bank->enabled = true;
        
        printf("[RAM] PSRAM initialized: %lu KB\n", hw->psram_size / 1024);
    }
    
    // Calculate available RAM
    state->available_external_ram = guikit_hw_get_external_ram(&state->config);
    
    #if defined(ESP8266)
        state->available_ram = 80 * 1024;  // ~80KB free on ESP8266
    #elif defined(ESP32)
        state->available_ram = 320 * 1024;  // ~320KB free on ESP32
    #else
        state->available_ram = 64 * 1024;  // Default: 64KB
    #endif
    
    state->available_ram += state->available_external_ram;
    
    return true;
}

/**
 * Initialize SD Card
 */
static bool init_sd_card(BootloaderState* state) {
    BootHardwareInfo* hw = &state->hardware;
    
    if (!hw->sdcard_detected) {
        printf("[SD] SD Card not detected, skipping\n");
        return false;
    }
    
    // Initialize SD Card (mock)
    state->sdcard_instance = nullptr;  // Would be new SDCard(hw->sdcard_cs_pin)
    
    // Check if SD Card is accessible
    // In a real implementation, this would try to read the card info
    printf("[SD] SD Card initialized at CS %d\n", hw->sdcard_cs_pin);
    
    return true;
}

/**
 * Initialize TFT display
 */
static bool init_tft(BootloaderState* state) {
    BootHardwareInfo* hw = &state->hardware;
    
    if (!hw->tft_detected) {
        printf("[TFT] TFT not detected, skipping\n");
        return false;
    }
    
    // Initialize TFT
    if (!tft_init(&state->tft_instance, hw->tft_cs_pin, hw->tft_width, hw->tft_height)) {
        state->current_state = BOOT_STATE_ERROR;
        state->error_message = "Failed to initialize TFT";
        return false;
    }
    
    // Clear screen
    tft_clear(state->tft_instance, BOOTLOADER_BG_COLOR);
    
    // Display boot header
    tft_draw_text(state->tft_instance, 10, 10, "GUIKit Bootloader", BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
    tft_draw_text(state->tft_instance, 10, 30, "Initializing...", BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
    
    printf("[TFT] TFT initialized: %dx%d at CS %d\n", hw->tft_width, hw->tft_height, hw->tft_cs_pin);
    
    return true;
}

// ============================================================================
// Memory Strategy Test
// ============================================================================

/**
 * Test memory strategy with sample GUI sizes
 * 
 * Demonstrates the STOP-at-first-success behavior:
 * 1. Try External RAM -> if success STOP
 * 2. Try SD Card Swap -> if success STOP  
 * 3. Try Internal RAM -> if success STOP
 * 4. Else FAILED
 */
static void test_memory_strategy(BootloaderState* state) {
    BootHardwareInfo* hw = &state->hardware;
    memory_strategy_config_t* cfg = &state->memory_config;
    
    printf("\n[MEMORY STRATEGY] Testing with detected hardware:\n");
    printf("  External RAM: %s (%lu KB)\n", 
           hw->sram_detected ? "Yes" : "No", hw->sram_size / 1024);
    printf("  SD Card: %s\n", hw->sdcard_detected ? "Yes" : "No");
    printf("  Internal RAM: ~%lu KB\n", state->available_ram / 1024);
    printf("\n");
    
    // Test different GUI sizes
    uint32_t test_sizes[] = {
        1024,      // 1KB - Small GUI
        4096,      // 4KB - Boundary for external RAM
        8192,      // 8KB - Boundary for internal RAM
        16384,     // 16KB - Boundary for SD swap
        32768,     // 32KB - Medium GUI
        65536,     // 64KB - Large GUI
        131072,    // 128KB - Very large GUI
        262144     // 256KB - Huge GUI
    };
    
    bool sram_avail = hw->sram_detected || hw->psram_detected;
    bool sdcard_avail = hw->sdcard_detected;
    
    printf("  Strategy Decision Flow (STOP at first success):\n");
    printf("  1. Try External RAM -> if (avail AND fits AND can_use) => SELECT & STOP\n");
    printf("  2. Try SD Card Swap -> if (avail AND fits AND can_use) => SELECT & STOP\n");
    printf("  3. Try Internal RAM -> if (fits AND can_use) => SELECT & STOP\n");
    printf("  4. Else => FAILED\n");
    printf("\n");
    
    for (int i = 0; i < sizeof(test_sizes) / sizeof(test_sizes[0]); i++) {
        uint32_t gui_size = test_sizes[i];
        MemoryStrategyLevel strategy = guikit_memory_strategy_select(
            cfg, gui_size, sram_avail, sdcard_avail
        );
        
        const char* strategy_name = "";
        switch (strategy) {
            case MEMORY_STRATEGY_EXTERNAL_RAM: strategy_name = "External RAM"; break;
            case MEMORY_STRATEGY_SD_SWAP: strategy_name = "SD Card Swap"; break;
            case MEMORY_STRATEGY_INTERNAL_RAM: strategy_name = "Internal RAM"; break;
            case MEMORY_STRATEGY_FAILED: strategy_name = "FAILED"; break;
        }
        
        printf("  GUI Size: %5lu KB -> Strategy: %s [STOP]\n", 
               gui_size / 1024, strategy_name);
        
        // If this is the first test, save it as the selected strategy
        if (i == 0) {
            state->selected_strategy = strategy;
        }
    }
    
    printf("\n");
}

// ============================================================================
// Bootloader Main Functions
// ============================================================================

/**
 * Initialize bootloader state
 */
static void bootloader_init(BootloaderState* state, const guikit_hw_config_t* platform_config) {
    memset(state, 0, sizeof(BootloaderState));
    
    // Set platform configuration
    if (platform_config) {
        state->config = *platform_config;
    } else {
        // Use default for current platform
        #if defined(ESP8266)
            state->config = GUIKIT_HW_ESP8266_DEFAULT;
        #elif defined(ESP32)
            state->config = GUIKIT_HW_ESP32_DEFAULT;
        #else
            state->config = GUIKIT_HW_DEFAULT;
        #endif
    }
    
    state->current_state = BOOT_STATE_INIT;
    state->error_message = NULL;
    state->sram_instance = nullptr;
    state->sdcard_instance = nullptr;
    state->tft_instance = nullptr;
    
    // Start timing
    state->boot_start_time = 0;  // Would use millis() or similar
}

/**
 * Run the complete bootloader sequence
 */
bool guikit_bootloader_run(BootloaderState* state) {
    printf("\n");
    printf("========================================\n");
    printf("GUIKit Bootloader Starting\n");
    printf("========================================\n");
    printf("\n");
    
    // Initialize hardware detection info
    memset(&state->hardware, 0, sizeof(BootHardwareInfo));
    
    // ---------------------------------------------------------------------------
    // Step 1: Hardware Detection
    // ---------------------------------------------------------------------------
    printf("[BOOT] Step 1/6: Hardware Detection\n");
    state->current_state = BOOT_STATE_HARDWARE_DETECTION;
    
    // Set platform info
    state->config.is_esp8266 = GUIKIT_PLATFORM_ESP8266;
    state->config.is_esp32 = GUIKIT_PLATFORM_ESP32;
    
    // Detect SPI devices
    detect_spi_devices(state);
    
    if (state->current_state == BOOT_STATE_ERROR) {
        printf("[BOOT] ERROR: %s\n", state->error_message);
        return false;
    }
    
    printf("[BOOT] Hardware detection complete\n");
    printf("  SRAM: %s, PSRAM: %s, SD Card: %s, TFT: %s, Touch: %s\n",
           state->hardware.sram_detected ? "Yes" : "No",
           state->hardware.psram_detected ? "Yes" : "No",
           state->hardware.sdcard_detected ? "Yes" : "No",
           state->hardware.tft_detected ? "Yes" : "No",
           state->hardware.touch_detected ? "Yes" : "No");
    printf("  SPI Expanders: %d, GPIO: %d\n",
           state->hardware.spi_expander_count,
           state->hardware.total_expander_gpio);
    printf("\n");
    
    // ---------------------------------------------------------------------------
    // Step 2: RAM Initialization
    // ---------------------------------------------------------------------------
    printf("[BOOT] Step 2/6: RAM Initialization\n");
    state->current_state = BOOT_STATE_RAM_INITIALIZATION;
    
    if (!init_ram(state)) {
        state->current_state = BOOT_STATE_ERROR;
        state->error_message = "Failed to initialize RAM";
        printf("[BOOT] ERROR: %s\n", state->error_message);
        return false;
    }
    
    printf("[BOOT] RAM initialization complete\n");
    printf("  Available RAM: %lu KB (Internal: ~%lu KB, External: %lu KB)\n",
           state->available_ram / 1024,
           (state->available_ram - state->available_external_ram) / 1024,
           state->available_external_ram / 1024);
    printf("\n");
    
    // ---------------------------------------------------------------------------
    // Step 3: SD Card Detection
    // ---------------------------------------------------------------------------
    printf("[BOOT] Step 3/6: SD Card Initialization\n");
    state->current_state = BOOT_STATE_SDCARD_DETECTION;
    
    if (state->hardware.sdcard_detected) {
        init_sd_card(state);
    }
    
    printf("[BOOT] SD Card initialization complete\n");
    printf("  SD Card: %s\n", state->hardware.sdcard_detected ? "Ready" : "Not available");
    printf("\n");
    
    // ---------------------------------------------------------------------------
    // Step 3.5: Kernel Check (if SD Card is available)
    // ---------------------------------------------------------------------------
    if (state->hardware.sdcard_detected) {
        printf("[BOOT] Step 3.5/6: Kernel Check\n");
        state->current_state = BOOT_STATE_KERNEL_CHECK;
        
        // Try all kernel paths until one is found
        bool kernel_found = false;
        for (int i = 0; KERNEL_PATHS[i] != NULL; i++) {
            if (check_kernel(state, KERNEL_PATHS[i])) {
                kernel_found = true;
                break;
            }
        }
        
        if (!kernel_found) {
            // Try default path
            kernel_found = check_kernel(state, "/kernel.bin");
        }
        
        if (!kernel_found) {
            state->current_state = BOOT_STATE_ERROR;
            state->error_message = "No valid kernel found on SD card";
            printf("[BOOT] ERROR: No valid kernel found on SD card\n");
            return false;
        }
        
        printf("[BOOT] Kernel check complete\n");
        printf("  Kernel: %lu KB at %s\n", 
               state->kernel.size / 1024, state->kernel.path);
        printf("  Fits in RAM: %s\n", state->kernel.fits_in_ram ? "Yes" : "No");
        printf("  Load Strategy: %s\n",
               state->kernel.strategy == MEMORY_STRATEGY_EXTERNAL_RAM ? "External RAM" :
               state->kernel.strategy == MEMORY_STRATEGY_SD_SWAP ? "SD Card Swap" :
               state->kernel.strategy == MEMORY_STRATEGY_INTERNAL_RAM ? "Internal RAM" : "FAILED");
        printf("\n");
        
        // If kernel doesn't fit in RAM, fail
        if (!state->kernel.fits_in_ram) {
            state->current_state = BOOT_STATE_ERROR;
            state->error_message = "Kernel too large for available RAM";
            printf("[BOOT] ERROR: %s\n", state->error_message);
            return false;
        }
        
        // If no valid strategy, fail
        if (state->kernel.strategy == MEMORY_STRATEGY_FAILED) {
            state->current_state = BOOT_STATE_ERROR;
            state->error_message = "No valid memory strategy for kernel";
            printf("[BOOT] ERROR: %s\n", state->error_message);
            return false;
        }
    } else {
        // No SD Card - set kernel info accordingly
        state->kernel.found = false;
        state->kernel.size = 0;
        state->kernel.fits_in_ram = false;
        state->kernel.strategy = MEMORY_STRATEGY_FAILED;
        printf("[BOOT] No SD Card - skipping kernel check (kernel must be in Flash)\n\n");
    }
    
    // ---------------------------------------------------------------------------
    // Step 4: TFT Initialization
    // ---------------------------------------------------------------------------
    printf("[BOOT] Step 4/7: TFT Initialization\n");
    state->current_state = BOOT_STATE_TFT_INITIALIZATION;
    
    if (state->hardware.tft_detected) {
        init_tft(state);
    }
    
    printf("[BOOT] TFT initialization complete\n");
    printf("  TFT: %s\n", state->hardware.tft_detected ? "Ready" : "Not available");
    printf("\n");
    
    // ---------------------------------------------------------------------------
    // Step 5: Memory Strategy Configuration
    // ---------------------------------------------------------------------------
    printf("[BOOT] Step 5/7: Memory Strategy Configuration\n");
    state->current_state = BOOT_STATE_MEMORY_STRATEGY_CONFIG;
    
    // Configure memory strategy based on detected hardware
    configure_memory_strategy(state);
    
    // Update the main config with the memory strategy
    state->config.memory_strategy = state->memory_config;
    
    printf("[BOOT] Memory strategy configured\n");
    printf("  Strategy thresholds:\n");
    printf("    External RAM min: %lu KB\n", state->memory_config.external_ram_min_size / 1024);
    printf("    SD Swap min: %lu KB\n", state->memory_config.sd_swap_min_size / 1024);
    printf("    Internal RAM max: %lu KB\n", state->memory_config.internal_ram_max_size / 1024);
    printf("  Flags:\n");
    printf("    Use External RAM: %s\n", state->memory_config.use_external_ram_by_default ? "Yes" : "No");
    printf("    Use SD Swap: %s\n", state->memory_config.use_sd_swap_by_default ? "Yes" : "No");
    printf("    Check Memory: %s\n", state->memory_config.check_memory_before_load ? "Yes" : "No");
    printf("    Display Errors: %s\n", state->memory_config.display_error_on_tft ? "Yes" : "No");
    printf("\n");
    
    // ---------------------------------------------------------------------------
    // Step 6: Memory Strategy Test and Apply
    // ---------------------------------------------------------------------------
    printf("[BOOT] Step 6/7: Memory Strategy Test and Apply\n");
    state->current_state = BOOT_STATE_MEMORY_STRATEGY_APPLY;
    
    // Test memory strategy with different GUI sizes
    test_memory_strategy(state);
    
    // Initialize memory strategy system
    gui_memory_strategy_init(
        state->sram_instance,
        state->sdcard_instance,
        state->tft_instance,
        &state->memory_config
    );
    
    printf("[BOOT] Memory strategy initialized\n");
    
    // Get current strategy info
    uint32_t total_ram, used_ram, free_ram;
    MemoryStrategyLevel current_strategy;
    gui_memory_strategy_get_stats(&total_ram, &used_ram, &free_ram, &current_strategy);
    
    printf("  Current Strategy: %s\n", 
           current_strategy == MEMORY_STRATEGY_EXTERNAL_RAM ? "External RAM" :
           current_strategy == MEMORY_STRATEGY_SD_SWAP ? "SD Swap" :
           current_strategy == MEMORY_STRATEGY_INTERNAL_RAM ? "Internal RAM" : "None");
    printf("\n");
    
    // ---------------------------------------------------------------------------
    // Display Results on TFT
    // ---------------------------------------------------------------------------
    if (state->hardware.tft_detected) {
        tft_clear(state->tft_instance, BOOTLOADER_BG_COLOR);
        
        int y = 10;
        tft_draw_text(state->tft_instance, 10, y, "GUIKit Bootloader", BOOTLOADER_SUCCESS_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        tft_draw_text(state->tft_instance, 10, y, "Hardware Detected:", BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        char buffer[64];
        
        snprintf(buffer, sizeof(buffer), "  RAM: %lu KB Int, %lu KB Ext",
                 (state->available_ram - state->available_external_ram) / 1024,
                 state->available_external_ram / 1024);
        tft_draw_text(state->tft_instance, 10, y, buffer, BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        snprintf(buffer, sizeof(buffer), "  SD Card: %s",
                 state->hardware.sdcard_detected ? "Yes" : "No");
        tft_draw_text(state->tft_instance, 10, y, buffer, BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        snprintf(buffer, sizeof(buffer), "  TFT: %dx%d",
                 state->hardware.tft_width, state->hardware.tft_height);
        tft_draw_text(state->tft_instance, 10, y, buffer, BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        snprintf(buffer, sizeof(buffer), "  Touch: %s",
                 state->hardware.touch_detected ? "Yes" : "No");
        tft_draw_text(state->tft_instance, 10, y, buffer, BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 30;
        
        tft_draw_text(state->tft_instance, 10, y, "Memory Strategy:", BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        const char* strategy_names[] = {
            "External RAM", "SD Swap", "Internal RAM", "Failed"
        };
        snprintf(buffer, sizeof(buffer), "  Strategy: %s",
                 strategy_names[state->selected_strategy]);
        tft_draw_text(state->tft_instance, 10, y, buffer, BOOTLOADER_SUCCESS_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        snprintf(buffer, sizeof(buffer), "  External > %lu KB",
                 state->memory_config.external_ram_min_size / 1024);
        tft_draw_text(state->tft_instance, 10, y, buffer, BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        snprintf(buffer, sizeof(buffer), "  SD Swap > %lu KB",
                 state->memory_config.sd_swap_min_size / 1024);
        tft_draw_text(state->tft_instance, 10, y, buffer, BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 20;
        
        snprintf(buffer, sizeof(buffer), "  Internal < %lu KB",
                 state->memory_config.internal_ram_max_size / 1024);
        tft_draw_text(state->tft_instance, 10, y, buffer, BOOTLOADER_TEXT_COLOR, BOOTLOADER_BG_COLOR);
        y += 30;
        
        tft_draw_text(state->tft_instance, 10, y, "Boot Complete!", BOOTLOADER_SUCCESS_COLOR, BOOTLOADER_BG_COLOR);
    }
    
    // ---------------------------------------------------------------------------
    // Finalize
    // ---------------------------------------------------------------------------
    state->current_state = BOOT_STATE_COMPLETE;
    state->boot_end_time = 0;  // Would use millis() or similar
    
    printf("========================================\n");
    printf("GUIKit Bootloader Complete\n");
    printf("========================================\n");
    printf("\n");
    printf("Boot Summary:\n");
    printf("  Platform: %s\n", 
           state->config.is_esp8266 ? "ESP8266" : (state->config.is_esp32 ? "ESP32" : "Unknown"));
    printf("  RAM: %lu KB total (%lu KB internal, %lu KB external)\n",
           state->available_ram / 1024,
           (state->available_ram - state->available_external_ram) / 1024,
           state->available_external_ram / 1024);
    printf("  SD Card: %s\n", state->hardware.sdcard_detected ? "Available" : "Not available");
    printf("  TFT: %s (%dx%d)\n", 
           state->hardware.tft_detected ? "Available" : "Not available",
           state->hardware.tft_width, state->hardware.tft_height);
    printf("  Touch: %s\n", state->hardware.touch_detected ? "Available" : "Not available");
    printf("  SPI Expanders: %d (%d GPIO)\n",
           state->hardware.spi_expander_count, state->hardware.total_expander_gpio);
    
    // Kernel information
    if (state->kernel.found) {
        printf("\n");
        printf("Kernel:\n");
        printf("  Found: Yes\n");
        printf("  Path: %s\n", state->kernel.path);
        printf("  Size: %lu KB\n", state->kernel.size / 1024);
        printf("  Version: %s\n", state->kernel.version ? state->kernel.version : "Unknown");
        printf("  Fits in RAM: %s\n", state->kernel.fits_in_ram ? "Yes" : "No");
        printf("  Load Strategy: %s\n",
               state->kernel.strategy == MEMORY_STRATEGY_EXTERNAL_RAM ? "External RAM" :
               state->kernel.strategy == MEMORY_STRATEGY_SD_SWAP ? "SD Card Swap" :
               state->kernel.strategy == MEMORY_STRATEGY_INTERNAL_RAM ? "Internal RAM" : "FAILED");
    } else {
        printf("\n");
        printf("Kernel:\n");
        printf("  Found: No (must be in Flash)\n");
    }
    
    printf("\n");
    printf("Memory Strategy:\n");
    printf("  Selected: %s\n",
           state->selected_strategy == MEMORY_STRATEGY_EXTERNAL_RAM ? "External RAM" :
           state->selected_strategy == MEMORY_STRATEGY_SD_SWAP ? "SD Swap" :
           state->selected_strategy == MEMORY_STRATEGY_INTERNAL_RAM ? "Internal RAM" : "Failed");
    printf("  Thresholds:\n");
    printf("    External RAM: > %lu KB\n", state->memory_config.external_ram_min_size / 1024);
    printf("    SD Swap: > %lu KB\n", state->memory_config.sd_swap_min_size / 1024);
    printf("    Internal RAM: < %lu KB\n", state->memory_config.internal_ram_max_size / 1024);
    printf("\n");
    
    return true;
}

// ============================================================================
// Example Usage
// ============================================================================

/**
 * Example: Full bootloader sequence for ESP8266 with external SRAM
 */
void example_esp8266_with_sram() {
    printf("\n");
    printf("========================================\n");
    printf("Example: ESP8266 with External SRAM\n");
    printf("========================================\n");
    printf("\n");
    
    // Create a custom configuration for ESP8266 with external SRAM
    guikit_hw_config_t platform_config = GUIKIT_HW_ESP8266_DEFAULT;
    
    // Add external SRAM bank
    platform_config.ram.bank_count = 1;
    platform_config.ram.bank[0].type = GUIKIT_RAM_SRAM;
    platform_config.ram.bank[0].size = 131072;  // 128KB
    platform_config.ram.bank[0].cs_pin = 16;    // D0
    platform_config.ram.bank[0].enabled = true;
    
    // Configure SPI for SRAM, TFT, Touch, SD Card
    platform_config.spi.bank_count = 4;
    platform_config.spi.bank[0].type = GUIKIT_SPI_DEVICE;
    platform_config.spi.bank[0].cs_pin = 15;     // TFT on D8
    platform_config.spi.bank[0].enabled = true;
    
    platform_config.spi.bank[1].type = GUIKIT_SPI_DEVICE;
    platform_config.spi.bank[1].cs_pin = 4;      // Touch on D2
    platform_config.spi.bank[1].enabled = true;
    
    platform_config.spi.bank[2].type = GUIKIT_SPI_DEVICE;
    platform_config.spi.bank[2].cs_pin = 5;      // SD on D1
    platform_config.spi.bank[2].enabled = true;
    
    platform_config.spi.bank[3].type = GUIKIT_SPI_DEVICE;
    platform_config.spi.bank[3].cs_pin = 16;     // SRAM on D0
    platform_config.spi.bank[3].enabled = true;
    
    // Run bootloader
    BootloaderState state;
    bootloader_init(&state, &platform_config);
    
    if (guikit_bootloader_run(&state)) {
        printf("Bootloader completed successfully!\n");
    } else {
        printf("Bootloader failed: %s\n", state.error_message);
    }
}

/**
 * Example: Full bootloader sequence for ESP8266 without external RAM
 */
